            state = '运行'
        elif state == '运行' and ev == 'IO等待':
            state = '阻塞'
        elif state == '阻塞' and ev == 'IO完成':
            state = '就绪'
        elif state == '运行' and ev == '完成':
            state = '终止'
    return state

