def tcp_handshake(states):
    # TCP 三次握手：CLOSED → SYN → SYN-ACK → ESTABLISHED
    state = 'CLOSED'
    for ev in states:
        if state == 'CLOSED' and ev == 'SYN':
            state = 'SYN_SENT'
        elif state == 'SYN_SENT' and ev == 'SYN-ACK':
            state = 'ESTABLISHED'
    return state

