    return max(rules, key=cascade_weight)
def cascade_weight(rule):
    # CSS 级联优先级：内联1000 > id100 > class10 > 标签1
    w = 0
    if rule.get('inline'):
        w += 1000
    w += 100 * len(rule.get('ids', []))
    w += 10 * len(rule.get('classes', []))
    w += 1 * len(rule.get('tags', []))
    return w

