def frame_decode(buf, delim=b'\r\n'):
    # 蜂群会话层：字节流按分隔符分帧（粘包/半包处理）
    frames = []
    while True:
        idx = buf.find(delim)
        if idx < 0:
            break
        frames.append(buf[:idx])
        buf = buf[idx + len(delim):]
    return frames, buf

