def page_fault_handler(page_table, vpn, free_frames, load):
    # 缺页处理：present=0 → 分配空闲帧加载；无空闲帧 → 拒绝（置换由上层调度）
    if vpn in page_table and page_table[vpn].get('present') == 1:
        return 'hit', page_table[vpn]['frame']
    if not free_frames:
        return 'page_fault_no_frame', None
    frame = free_frames.pop(0)
    page_table[vpn] = {'present': 1, 'frame': frame}
    load(vpn, frame)
    return 'page_fault_loaded', frame

