def style_compute(node, rules):
    # 样式计算：DOM 节点（tag/classes）→ 匹配规则级联 → 最终样式
    best, best_w = {}, -1
    for rule in rules:
        if rule.get('tag') and rule['tag'] != node.get('tag'):
            continue
        if rule.get('class') and rule['class'] not in node.get('classes', []):
            continue
        w = (1000 if rule.get('inline') else 0)
        w += 100 if rule.get('id') else 0
        w += 10 if rule.get('class') else 0
        w += 1 if rule.get('tag') else 0
        if w > best_w:
            best, best_w = rule.get('style', {}), w
    return best

