def paint(layout, rows, cols):
    # 绘制：布局树 → 字符画布（'#'=元素区域，'.'=空白）
    canvas = [['.' for _ in range(cols)] for _ in range(rows)]
    for _, x, y, w, h in layout:
        for dy in range(h):
            for dx in range(w):
                if 0 <= y + dy < rows and 0 <= x + dx < cols:
                    canvas[y + dy][x + dx] = '#'
    return [''.join(row) for row in canvas]
